loadJs:
const apiHost = 'https://apibi.cc';
const tokenKey = CryptoJS.MD5('book@token.html').toString();
const tokenIv = CryptoJS.enc.Utf8.parse(tokenKey.slice(0, 16));
const tokenSecret = CryptoJS.enc.Utf8.parse(tokenKey.slice(16));
function encodeToken(value) {
  return CryptoJS.AES.encrypt(JSON.stringify(value), tokenSecret, {
    iv: tokenIv,
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7
  }).toString();
}
function apiUrl(name, params) {
  return apiHost + '/api/' + name + '?token=' + encodeURIComponent(encodeToken(params));
}

chapterUrl:
@js:(() => {
  const id = Number(result);
  return apiUrl('booklist', {id}) + '&bookid=' + id;
})()

